int add(int x, int y);
main.cpp:#include "add.h"
#include <iostream>
int main()
{
 std::cout << "The sum of 3 and 4 is " << add(3, 4) << '\n';
 return 0;
}
add.cpp:#include "add.h"         // copies forward declaration from add.h here
double add(int x, int y) // oops, return type is double instead of int
{
 return x + y;
}
When add.cpp is compiled, the forward declaration int add(int x, int y) will be copied into add.cpp at the point of the #include.
